from common import *
P=R/'projects/game-math-lines-circles-v2';H=P/'production/concept-fit-v2';T=read(H/'timeline.json');D=P/'publishing/revisions/concept-fit-v2';D.mkdir(parents=True,exist_ok=True)
en=['Add connections and bounds to oriented objects','Turning shapes into calculations','Two visible endpoints','Why start with a circle?','Three representations of one circle','A translated center needs linear terms','From a translated circle to a connecting line','Cable endpoints and the calculation segment','Fixed origin, near and far endpoints','Connection segment versus actual movement path','Lines, segments and rays have different domains','Check the units of ratios and distance','Compare a ratio and meters at the same point','The same parameter rule with a new endpoint','Move the endpoint to make a vertical line','Equal distances produce a vertical line','Normal form and the perpendicular bisector','The connection is ready; the object bounds remain']
assert len(en)==len(T['scenes'])
def stamp(t):n=int(t);return f'{n//60:02}:{n%60:02}'
for lang in ['ko','en']:
 old=(P/f'publishing/upload-description.{lang}.txt').read_text(encoding='utf8');footer='🎮'+old.split('🎮',1)[1]
 intro='두 점을 연결할 때 필요한 정보는 무엇일까요? 그래플의 두 끝점과 건축 게임의 배선을 관찰한 뒤, 원의 표현에서 직선·선분·레이, 비율과 거리, 수직선과 법선까지 기존 강의 순서대로 계산합니다.' if lang=='ko' else 'What information connects two points? Observe grapple endpoints and construction wiring, then follow the original lesson through circles, lines, segments, rays, ratios, distances, vertical lines and normals.'
 note='실제 화면의 연결선·케이블과 자체 계산 모형을 구분합니다. 화면 픽셀이나 표식을 게임 내부 거리·충돌·물리의 측정값으로 사용하지 않습니다. 별도 배경음악은 추가하지 않았습니다.' if lang=='ko' else 'Visible connections and cables are distinguished from our mathematical models. Screen pixels and guides are not measurements of internal game distances, collision or physics. No separate background-music track was added.'
 chapters='\n'.join(stamp(0 if i==0 else s['start'])+' '+(s['title'] if lang=='ko' else en[i]) for i,s in enumerate(T['scenes']))
 credits='\n\n'+('게임 화면 출처' if lang=='ko' else 'Gameplay sources')+'\nA Story About My Uncle — Coffee Stain / Gone North Games. Recording: LUXURY GAMEZ, labeled Free To Use Gameplay; contextual explanation and annotations.\nhttps://www.youtube.com/watch?v=5u3sUKuncSU\nSatisfactory — Coffee Stain Studios. Official Press & Content Creators asset kit, Update1.2 construction excerpt.\nhttps://www.satisfactorygame.com/press/\n'
 (D/f'upload-description.{lang}.txt').write_text(intro+'\n\n'+note+'\n\n'+('챕터' if lang=='ko' else 'Chapters')+'\n'+chapters+'\n'+stamp(T['seconds']-10)+' '+('멤버십 감사와 코칭 안내' if lang=='ko' else 'Membership thanks and programming coaching')+'\n\n'+footer.rstrip()+credits,encoding='utf8')
save(H/'description-drafts.json',dict(status='local drafts only',files=[dict(path=rel(x),sha256=sha(x)) for x in D.glob('*.txt')],creditsAtBottom=True,uploadAuthorized=False))
